-- Versioned workspace recovery. Only the JWT/password-verifying Edge handler may invoke mutations.
begin;
create table public.workspace_owners(shop_id uuid primary key references shops(id),user_id uuid not null references auth.users(id),established_at timestamptz not null default now(),provenance text not null);
create table public.workspace_lifecycle_audit(id uuid primary key default gen_random_uuid(),shop_id uuid,actor uuid not null,action text not null,old_value jsonb,new_value jsonb,reason text,created_at timestamptz not null default now());
create table public.workspace_recovery(shop_id uuid primary key references shops(id),pending_at timestamptz,delete_after timestamptz,backup_checksum text,backup_at timestamptz,backup_id uuid,requested_by uuid,check(delete_after is null or delete_after>=pending_at+interval '30 days'));
create table public.workspace_verified_backups(id uuid primary key default gen_random_uuid(),shop_id uuid not null references shops(id),actor uuid not null,checksum text not null check(checksum~'^[0-9a-f]{64}$'),created_at timestamptz not null default now(),format_version integer not null default 1);
create table public.workspace_backup_tables(table_name text primary key,columns text[] not null);
alter table workspace_owners enable row level security;alter table workspace_recovery enable row level security;alter table workspace_lifecycle_audit enable row level security;alter table workspace_verified_backups enable row level security;alter table workspace_backup_tables enable row level security;
revoke all on workspace_owners,workspace_recovery,workspace_lifecycle_audit,workspace_verified_backups,workspace_backup_tables from public,anon,authenticated;
-- Existing businesses get the oldest active administrator, never whichever account clicks first.
insert into workspace_owners(shop_id,user_id,provenance) select distinct on(shop_id) shop_id,user_id,'migration: oldest active administrator; review ownership before launch' from staff_profiles where active and role='admin' order by shop_id,created_at,user_id;
insert into workspace_lifecycle_audit(shop_id,actor,action,new_value,reason) select shop_id,user_id,'owner_backfill',jsonb_build_object('user_id',user_id),provenance from workspace_owners;
create function public.workspace_owner() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from workspace_owners o join staff_profiles s on s.shop_id=o.shop_id and s.user_id=o.user_id where o.user_id=auth.uid() and s.active and s.role='admin' and not s.must_change_password)$$;
revoke all on function workspace_owner() from public,anon;grant execute on function workspace_owner() to authenticated;
-- Freeze a reviewed structural allowlist; future migrations explicitly register their business tables.
insert into workspace_backup_tables select c.table_name,array_agg(c.column_name order by c.ordinal_position) from information_schema.columns c where c.table_schema='public' and c.is_generated='NEVER' and c.table_name in(select table_name from information_schema.tables where table_schema='public' and table_type='BASE TABLE') and c.column_name!~*'(password|pin_hash|secret|api_key|(^|_)token$|credential)' and c.table_name in(select table_name from information_schema.columns where table_schema='public' and column_name='shop_id') and c.table_name not in('staff_profiles','workspace_owners','workspace_recovery','workspace_verified_backups','workspace_lifecycle_audit','ux_user_preferences','staff_access_audit','backup_exports','staff_ops_permissions') group by c.table_name;
create function public.workspace_clean_json(p_value jsonb) returns jsonb language plpgsql immutable set search_path=public as $$declare result jsonb;begin if jsonb_typeof(p_value)='object' then select coalesce(jsonb_object_agg(key,workspace_clean_json(value)),'{}') into result from jsonb_each(p_value) where key!~*'(password|pin_hash|secret|api_key|(^|_)token$|credential)';return result;elsif jsonb_typeof(p_value)='array' then select coalesce(jsonb_agg(workspace_clean_json(value)),'[]') into result from jsonb_array_elements(p_value);return result;else return p_value;end if;end$$;
create function public.workspace_export(p_actor uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare s uuid;t record;rows jsonb;tables jsonb:='{}';shop jsonb;begin select shop_id into s from staff_profiles where user_id=p_actor and active and role='admin' and not must_change_password;if s is null then raise exception 'Administrator access required';end if;select workspace_clean_json(to_jsonb(x)) into shop from shops x where id=s;for t in select * from workspace_backup_tables loop execute format('select coalesce(jsonb_agg(workspace_clean_json(to_jsonb(x))),''[]''::jsonb) from (select %s from public.%I where shop_id=$1) x',(select string_agg(quote_ident(c),',') from unnest(t.columns)c),t.table_name) into rows using s;tables:=tables||jsonb_build_object(t.table_name,rows);end loop;return jsonb_build_object('shop',shop,'tables',tables,'staff_directory',(select coalesce(jsonb_agg(jsonb_build_object('display_name',display_name,'role',role,'active',active)),'[]') from staff_profiles where shop_id=s));end$$;
create function public.workspace_storage_files(p_actor uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare s uuid;begin select shop_id into s from staff_profiles where user_id=p_actor and active and role='admin' and not must_change_password;if s is null then raise exception 'Administrator access required';end if;return(select coalesce(jsonb_agg(jsonb_build_object('bucket',bucket_id,'name',name)),'[]') from storage.objects where split_part(name,'/',1)=s::text and bucket_id in('product-images','shop-logos','catalogue-media','special-order-references','ingredient-packages','recipe-steps','supply-imports'));end$$;
create function public.workspace_auth_columns() returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_object_agg(t,cols),'{}') from(select cl.relname t,jsonb_agg(a.attname) cols from pg_constraint c join pg_class cl on cl.oid=c.conrelid join pg_namespace ns on ns.oid=cl.relnamespace join pg_class target on target.oid=c.confrelid join pg_namespace tn on tn.oid=target.relnamespace join pg_attribute a on a.attrelid=c.conrelid and a.attnum=c.conkey[1] where c.contype='f' and ns.nspname='public' and(tn.nspname='auth' or target.relname='staff_profiles') group by cl.relname)x$$;
create function public.workspace_actor_state(p_actor uuid) returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('shop_id',s.shop_id,'business_name',b.name,'is_owner',exists(select 1 from workspace_owners o where o.shop_id=s.shop_id and o.user_id=p_actor),'is_admin',s.active and s.role='admin' and not s.must_change_password,'pending_at',r.pending_at,'delete_after',r.delete_after,'last_backup_at',(select max(created_at) from workspace_verified_backups where shop_id=s.shop_id)) from staff_profiles s join shops b on b.id=s.shop_id left join workspace_recovery r on r.shop_id=s.shop_id where s.user_id=p_actor$$;
create function public.workspace_verify_backup(p_actor uuid,p_checksum text) returns uuid language plpgsql security definer set search_path=public as $$declare s uuid;v uuid;begin select shop_id into s from staff_profiles where user_id=p_actor and role='admin' and active and not must_change_password;if s is null then raise exception 'Administrator access required';end if;insert into workspace_verified_backups(shop_id,actor,checksum) values(s,p_actor,p_checksum) returning id into v;insert into workspace_lifecycle_audit(shop_id,actor,action,new_value) values(s,p_actor,'backup_verified',jsonb_build_object('backup_id',v,'checksum',p_checksum));return v;end$$;
create function public.workspace_set_deletion(p_actor uuid,p_backup uuid,p_checksum text,p_name text,p_confirm boolean,p_final boolean) returns timestamptz language plpgsql security definer set search_path=public as $$declare s uuid;b workspace_verified_backups%rowtype;due timestamptz;begin select o.shop_id into s from workspace_owners o join staff_profiles p on p.user_id=o.user_id and p.shop_id=o.shop_id where o.user_id=p_actor and p.active and p.role='admin' and not p.must_change_password;if s is null then raise exception 'Workspace owner required';end if;perform 1 from shops where id=s and name=p_name for update;if not found or not coalesce(p_confirm,false) or not coalesce(p_final,false) then raise exception 'Exact business name and both confirmations are required';end if;select * into b from workspace_verified_backups where id=p_backup and shop_id=s and actor=p_actor and checksum=p_checksum and created_at>now()-interval '15 minutes';if b.id is null then raise exception 'A freshly generated and server-validated backup is required';end if;due:=now()+interval '30 days';insert into workspace_recovery(shop_id,pending_at,delete_after,backup_checksum,backup_at,backup_id,requested_by) values(s,now(),due,p_checksum,b.created_at,b.id,p_actor) on conflict(shop_id) do update set pending_at=excluded.pending_at,delete_after=excluded.delete_after,backup_checksum=excluded.backup_checksum,backup_at=excluded.backup_at,backup_id=excluded.backup_id,requested_by=excluded.requested_by where workspace_recovery.pending_at is null;if not found then raise exception 'Workspace is already pending deletion';end if;insert into workspace_lifecycle_audit(shop_id,actor,action,old_value,new_value,reason) values(s,p_actor,'deletion_pending',jsonb_build_object('status','active'),jsonb_build_object('delete_after',due,'checksum',p_checksum),'Owner password and explicit confirmations verified by Edge handler');return due;end$$;
create function public.workspace_cancel_deletion(p_actor uuid) returns void language plpgsql security definer set search_path=public as $$declare s uuid;old workspace_recovery%rowtype;begin select o.shop_id into s from workspace_owners o join staff_profiles p on p.user_id=o.user_id and p.shop_id=o.shop_id where o.user_id=p_actor and p.active and p.role='admin' and not p.must_change_password;if s is null then raise exception 'Workspace owner required';end if;select * into old from workspace_recovery where shop_id=s for update;if old.pending_at is null then raise exception 'No pending deletion';end if;if old.delete_after<=now() then raise exception 'Recovery period has expired; contact the deployment administrator';end if;update workspace_recovery set pending_at=null,delete_after=null where shop_id=s;insert into workspace_lifecycle_audit(shop_id,actor,action,old_value,new_value) values(s,p_actor,'deletion_cancelled',jsonb_build_object('delete_after',old.delete_after),jsonb_build_object('status','active'));end$$;
-- Pending workspaces stop resolving through ordinary staff RPC/RLS. Recovery Edge calls use actor lookup.
create or replace function public.current_shop_id() returns uuid language sql stable security definer set search_path=public as $$select s.shop_id from staff_profiles s where s.user_id=auth.uid() and s.active and not s.must_change_password and not exists(select 1 from workspace_recovery r where r.shop_id=s.shop_id and r.pending_at is not null)$$;
-- Token-based public order functions also pass through these guards; pending shops cannot accept new work.
create function public.workspace_pending_write_guard() returns trigger language plpgsql security definer set search_path=public as $$declare s uuid;begin s:=coalesce((case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end)->>'shop_id',(case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end)->>'id')::uuid;if coalesce(current_setting('workspace.lifecycle_mode',true),'')<>'purge' and exists(select 1 from workspace_recovery where shop_id=s and pending_at is not null) then raise exception 'Workspace is pending deletion; cancel recovery before resuming operations';end if;if tg_op='DELETE' then return old;else return new;end if;end$$;
revoke all on function workspace_pending_write_guard() from public,anon,authenticated;
do $$declare t record;begin for t in select table_name from workspace_backup_tables union select 'shops' loop execute format('create trigger workspace_pending_guard before insert or update or delete on public.%I for each row execute function public.workspace_pending_write_guard()',t.table_name);end loop;end$$;
-- Create ownership only in the same transaction as a first-time bootstrap.
alter function public.bootstrap_business(text,text,text,text) rename to bootstrap_business_before_recovery;
revoke all on function bootstrap_business_before_recovery(text,text,text,text) from public,anon,authenticated;
create function public.bootstrap_business(p_shop_name text,p_phone text,p_address text,p_display_name text) returns uuid language plpgsql security definer set search_path=public as $$declare s uuid;begin if exists(select 1 from staff_profiles where user_id=auth.uid()) and not workspace_owner() then raise exception 'Existing workspace owner required';end if;s:=bootstrap_business_before_recovery(p_shop_name,p_phone,p_address,p_display_name);insert into workspace_owners(shop_id,user_id,provenance) values(s,auth.uid(),'authenticated first-time business setup') on conflict(shop_id) do nothing;insert into workspace_lifecycle_audit(shop_id,actor,action,new_value) values(s,auth.uid(),'owner_established',jsonb_build_object('user_id',auth.uid()));return s;end$$;
revoke all on function bootstrap_business(text,text,text,text) from public,anon;grant execute on function bootstrap_business(text,text,text,text) to authenticated;
create function public.workspace_health() returns jsonb language plpgsql stable security definer set search_path=public as $$declare s uuid;begin select shop_id into s from staff_profiles where user_id=auth.uid() and active and role='admin' and not must_change_password;if s is null then raise exception 'Administrator access required';end if;return jsonb_build_object('database','connected','migration','202610171200_workspace_recovery','storage',case when exists(select 1 from storage.buckets where id='product-images') then 'configured; upload/download probe not performed' else 'missing product-images bucket' end,'edge','unknown until authenticated Edge probe','last_backup_at',(select max(created_at) from workspace_verified_backups where shop_id=s),'owner_established',exists(select 1 from workspace_owners where shop_id=s),'pending_deletion',(select delete_after from workspace_recovery where shop_id=s and pending_at is not null));end$$;
revoke all on function workspace_health() from public,anon;grant execute on function workspace_health() to authenticated;
-- Atomic new-ID restore. No existing workspace may be replaced or membership moved.
create function public.workspace_restore(p_actor uuid,p_data jsonb,p_checksum text) returns uuid language plpgsql security definer set search_path=public as $$declare s uuid;pair record;t workspace_backup_tables%rowtype;r jsonb;cols text;remaining jsonb;next_remaining jsonb;progress integer;fk record;v text;nullable_cols text[];deferred jsonb:='[]';pending_row jsonb;key_values jsonb;assignments text;predicates text;seq text;max_id bigint;begin
 if exists(select 1 from staff_profiles where user_id=p_actor) then raise exception 'Restore requires a new account without an existing workspace';end if;
 if not exists(select 1 from auth.users where id=p_actor) then raise exception 'Authenticated account required';end if;
 s:=(p_data->'shop'->>'id')::uuid;if s is null or exists(select 1 from shops where id=s) then raise exception 'Restore must use a new workspace ID';end if;
 if p_checksum!~'^[0-9a-f]{64}$' then raise exception 'Invalid backup checksum';end if;
 if workspace_clean_json(p_data)<>p_data then raise exception 'Credential fields are prohibited';end if;
 -- A forged archive cannot use public FKs to attach rows to an existing foreign tenant.
 for pair in select * from jsonb_each(p_data->'tables') loop
  select * into t from workspace_backup_tables where table_name=pair.key;if t.table_name is null then raise exception 'Unsupported restore table: %',pair.key;end if;
  for r in select value from jsonb_array_elements(pair.value) loop
   if r->>'shop_id'<>s::text or r->>'shop_id' is null then raise exception 'Foreign workspace row';end if;
   if exists(select 1 from jsonb_object_keys(r) k where not(k=any(t.columns))) then raise exception 'Unsupported restore column';end if;
   for fk in select a.attname as col,ct.relname as target,ca.attname as target_col,ns.nspname as target_schema from pg_constraint c join pg_class ct on ct.oid=c.confrelid join pg_namespace ns on ns.oid=ct.relnamespace join pg_attribute a on a.attrelid=c.conrelid and a.attnum=c.conkey[1] join pg_attribute ca on ca.attrelid=c.confrelid and ca.attnum=c.confkey[1] where c.contype='f' and c.conrelid=format('public.%I',pair.key)::regclass loop
    v:=r->>fk.col;if v is null then continue;end if;
    if fk.target_schema='auth' or fk.target='staff_profiles' then if v<>p_actor::text then raise exception 'Foreign authentication reference';end if;
    elsif fk.target='shops' then if v<>s::text then raise exception 'Foreign workspace reference';end if;
    elsif not exists(select 1 from jsonb_array_elements(coalesce(p_data->'tables'->fk.target,'[]')) x where x->>fk.target_col=v) then raise exception 'Reference is outside this backup: %.%',pair.key,fk.col;end if;
   end loop;
  end loop;
 end loop;
 select string_agg(quote_ident(c.column_name),',') into cols from information_schema.columns c where table_schema='public' and table_name='shops' and c.is_generated='NEVER' and p_data->'shop' ? c.column_name;
 execute format('insert into public.shops(%s) select %s from jsonb_populate_record(null::public.shops,$1)',cols,cols) using p_data->'shop';
 insert into staff_profiles(user_id,shop_id,display_name,role,email,must_change_password) select p_actor,s,coalesce(u.raw_user_meta_data->>'display_name','Workspace owner'),'admin',u.email,false from auth.users u where id=p_actor;
 insert into workspace_owners(shop_id,user_id,provenance) values(s,p_actor,'verified backup restore into new workspace');
 -- Break legitimate nullable FK cycles (paid sale ↔ scheduled order, trace links) and reconnect after all rows exist.
 for pair in select * from jsonb_each(p_data->'tables') loop
  select array_agg(a.attname) into nullable_cols from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=c.conkey[1] join pg_class target on target.oid=c.confrelid join pg_namespace ns on ns.oid=target.relnamespace where c.contype='f' and c.conrelid=format('public.%I',pair.key)::regclass and not a.attnotnull and ns.nspname='public' and target.relname not in('shops','staff_profiles') and exists(with recursive reach(rel,seen) as (select c.confrelid,array[c.confrelid] union all select edge.confrelid,r.seen||edge.confrelid from reach r join pg_constraint edge on edge.conrelid=r.rel and edge.contype='f' where not edge.confrelid=any(r.seen)) select 1 from reach where rel=c.conrelid);
  if nullable_cols is null then continue;end if;
  for r in select value from jsonb_array_elements(pair.value) loop
   if not exists(select 1 from unnest(nullable_cols)c where r->>c is not null) then continue;end if;
   select jsonb_object_agg(a.attname,r->a.attname) into key_values from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=any(c.conkey) where c.contype='p' and c.conrelid=format('public.%I',pair.key)::regclass;
   if key_values is null then raise exception 'Restore table has no safe primary key';end if;
   deferred:=deferred||jsonb_build_array(jsonb_build_object('table',pair.key,'keys',key_values,'values',(select jsonb_object_agg(c,r->c) from unnest(nullable_cols)c where r ? c)));
  end loop;
 end loop;
 remaining:=p_data->'tables';
 loop exit when remaining='{}'::jsonb;progress:=0;next_remaining:='{}';
  for pair in select * from jsonb_each(remaining) loop
   select * into t from workspace_backup_tables where table_name=pair.key;
   begin
    for r in select value from jsonb_array_elements(pair.value) loop
     select array_agg(a.attname) into nullable_cols from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=c.conkey[1] join pg_class target on target.oid=c.confrelid join pg_namespace ns on ns.oid=target.relnamespace where c.contype='f' and c.conrelid=format('public.%I',pair.key)::regclass and not a.attnotnull and ns.nspname='public' and target.relname not in('shops','staff_profiles') and exists(with recursive reach(rel,seen) as (select c.confrelid,array[c.confrelid] union all select edge.confrelid,r.seen||edge.confrelid from reach r join pg_constraint edge on edge.conrelid=r.rel and edge.contype='f' where not edge.confrelid=any(r.seen)) select 1 from reach where rel=c.conrelid);
     if nullable_cols is not null then r:=r-nullable_cols;end if;
     select string_agg(quote_ident(k),',') into cols from jsonb_object_keys(r) k;
     if cols is not null then execute format('insert into public.%I(%s) overriding system value select %s from jsonb_populate_record(null::public.%I,$1)',pair.key,cols,cols,pair.key) using r;end if;
    end loop;progress:=progress+1;
   exception when foreign_key_violation then next_remaining:=next_remaining||jsonb_build_object(pair.key,pair.value);
   end;
  end loop;
  if progress=0 then raise exception 'Restore has unresolved or cyclic references; no data was committed';end if;remaining:=next_remaining;
 end loop;
 for pending_row in select value from jsonb_array_elements(deferred) loop
  select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',k,pending_row->>'table',k),',') into assignments from jsonb_object_keys(pending_row->'values')k;
  select string_agg(format('t.%I is not distinct from (jsonb_populate_record(null::public.%I,$2)).%I',k,pending_row->>'table',k),' and ') into predicates from jsonb_object_keys(pending_row->'keys')k;
  execute format('update public.%I t set %s where t.shop_id=$3 and %s',pending_row->>'table',assignments,predicates) using pending_row->'values',pending_row->'keys',s;
 end loop;
 -- Imported business numbers keep their history; future identity values stay above all restored records.
 for pair in select c.table_name,c.column_name from information_schema.columns c where c.table_schema='public' and c.is_identity='YES' and p_data->'tables' ? c.table_name loop
  seq:=pg_get_serial_sequence(format('public.%I',pair.table_name),pair.column_name);
  if seq is not null then execute format('select greatest(coalesce(max(%I),0),1) from public.%I',pair.column_name,pair.table_name) into max_id;execute format('select greatest($1,last_value) from %s',seq) into max_id using max_id;perform setval(seq,max_id,true);end if;
 end loop;
 insert into workspace_lifecycle_audit(shop_id,actor,action,new_value,reason) values(s,p_actor,'backup_restored',jsonb_build_object('checksum',p_checksum,'new_workspace_id',s),'Validated archive; all internal IDs remapped; authentication accounts excluded');return s;
end$$;
-- Purge is never automatic from a browser timer. A server operator must enable it and an owner must reauthenticate.
create function public.workspace_purge_expired(p_actor uuid,p_name text) returns uuid language plpgsql security definer set search_path=public as $$declare s uuid;t record;leftover integer;progress integer;affected integer;begin
 select o.shop_id into s from workspace_owners o join staff_profiles p on p.user_id=o.user_id and p.shop_id=o.shop_id join shops b on b.id=o.shop_id join workspace_recovery r on r.shop_id=o.shop_id where o.user_id=p_actor and p.active and p.role='admin' and not p.must_change_password and b.name=p_name and r.pending_at is not null and r.delete_after<=now() for update of b,r;
 if s is null then raise exception 'Owner confirmation and expired 30-day recovery period required';end if;
 perform set_config('workspace.lifecycle_mode','purge',true);
 loop progress:=0;leftover:=0;
  for t in select distinct table_name from information_schema.columns where table_schema='public' and column_name='shop_id' and table_name<>'workspace_lifecycle_audit' and table_name in(select table_name from information_schema.tables where table_schema='public' and table_type='BASE TABLE') loop
   begin execute format('delete from public.%I where shop_id=$1',t.table_name) using s;get diagnostics affected=row_count;progress:=progress+affected;exception when foreign_key_violation then leftover:=leftover+1;end;
  end loop;
  exit when leftover=0;if progress=0 then raise exception 'Dependent records prevent safe purge; no deletion committed';end if;
 end loop;
 delete from shops where id=s;insert into workspace_lifecycle_audit(shop_id,actor,action,old_value,reason) values(s,p_actor,'workspace_purged',jsonb_build_object('business_name',p_name),'Owner reauthenticated after recovery expiry; operator-enabled purge');return s;
end$$;
-- Only service-role Edge calls get privileged RPCs. Untrusted browser calls cannot claim p_actor.
do $$declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('workspace_export','workspace_storage_files','workspace_auth_columns','workspace_actor_state','workspace_verify_backup','workspace_set_deletion','workspace_cancel_deletion','workspace_restore','workspace_purge_expired') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end$$;
revoke all on function workspace_clean_json(jsonb) from public,anon,authenticated;
commit;





